  describe('Codex PreToolUse hook compatibility', () => {
  it('allows safe commands and returns nested hookSpecificOutput', () => {
    const { stdout, exitCode } = runHook({
      tool_name: 'Bash',
      tool_input: { command: 'ls -la' },
    });
